void DialerTextareaDialerKey(lv_event_t * e)
{
    // Your code here
    lv_event_code_t code = lv_event_get_code(e);
    uint32_t key = lv_event_get_key(e);
    if(s_is_star){
        if(code == LV_EVENT_LONG_PRESSED){
            lv_textarea_del_char(ui_TextareaDialer);
            lv_textarea_add_char(ui_TextareaDialer, '+');
            lv_indev_wait_release(lv_indev_get_act());
            s_is_star = false;
        }
    }
    if(code == LV_EVENT_KEY){
        s_is_star = false;
        switch (key) {
        case LV_KEY_END:
            alv_am_app_exit(NULL, "call", NULL);
            LV_LOG_USER("[key test] back to idle app");
            have_input = false;
            break;
        case LV_KEY_GREEN:
            DialerKbdDialerValueChanged(e);
            LV_LOG_USER("[key test] LV_KEY_GREEN ,go to outgoing win");
            break;
        case LV_KEY_BACKSPACE:
            if (strlen(lv_textarea_get_text(ui_TextareaDialer)) == 0) {
                LV_LOG_USER("[key test] LV_KEY_BACKSPACE ,text length = 0");
                if (have_input == false) {
                    lv_indev_wait_release(lv_indev_get_act());
                    alv_am_app_exit(NULL, "call", NULL);
                    LV_LOG_USER("[key test] LV_KEY_BACKSPACE , back to idle app");
                    LV_LOG_USER("[key test] LV_KEY_BACKSPACE , have_input = false");
                }else{
                    LV_LOG_USER("[key test] LV_KEY_BACKSPACE , have_input = true");
                    have_input = false;
                }
            }
            break;
        case LV_KEY_0:
        case LV_KEY_1:
        case LV_KEY_2:
        case LV_KEY_3:
        case LV_KEY_4:
        case LV_KEY_5:
        case LV_KEY_6:
        case LV_KEY_7:
        case LV_KEY_8:
        case LV_KEY_9:
            have_input = true;
            LV_LOG_INFO("use default key event");
            break;
        case LV_KEY_HASH:
            lv_textarea_add_char(ui_TextareaDialer, '#');
            LV_LOG_USER("[key test] LV_KEY_HASH ");
            have_input = true;
            break;
        case LV_KEY_STAR:
            LV_LOG_USER("[key test] LV_KEY_STAR ");
            lv_textarea_add_char(ui_TextareaDialer, '*');
            have_input = true;
            s_is_star = true;
            break;
        default:
            LV_LOG_USER("[key test] dialer,other keys");
            if (strlen(lv_textarea_get_text(ui_TextareaDialer)) != 0){
                have_input = true;
            }
            LV_LOG_USER("[key test] key = %d , have_input = %d",key,have_input);
            break;
        }
    }
}

void DialerKbdDialerValueChanged(lv_event_t * e)
{
    // Your code here
    const char *p_temp_phone_num = NULL;
    char phone_num[33] = {0};

    p_temp_phone_num = lv_textarea_get_text(ui_TextareaDialer);

    memcpy(phone_num, p_temp_phone_num, 32);
    LV_LOG_USER("[key test] phone_num = %s",phone_num);
    call_flow_dial(phone_num, HandleDialerResult);
}
